{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈砚",
      "role": "protagonist",
      "identity": "法租界首席法医，留洋归国的医学博士",
      "traits": ["冷静理智", "内心孤独", "技术偏执", "嘴硬心软", "民族自尊心强"],
